'use strict';
const input = document.querySelector('#search');
const filters = [...document.querySelectorAll('[data-filter]')];
const cards = [...document.querySelectorAll('[data-category]')];
const count = document.querySelector('#result-count');
const empty = document.querySelector('#empty-state');
const clear = document.querySelector('.clear-search');
let selected = 'all';
function normalize(value) { return value.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g, '').replace(/[-&/]+/g, ' ').trim(); }
function update() {
  const words = normalize(input.value).split(/\s+/).filter(Boolean);
  let visible = 0;
  for (const card of cards) {
    const matches = (selected === 'all' || selected === card.dataset.category) && words.every(word => normalize(card.dataset.search).includes(word));
    card.hidden = !matches;
    if (matches) visible++;
  }
  count.textContent = visible + (visible === 1 ? ' listing' : ' listings') + ' to explore';
  empty.hidden = visible !== 0;
  clear.hidden = input.value.length === 0;
  for (const button of filters) button.setAttribute('aria-pressed', String(button.dataset.filter === selected));
}
input.addEventListener('input', update);
document.querySelector('.search-form').addEventListener('submit', event => event.preventDefault());
filters.forEach(button => button.addEventListener('click', () => { selected = button.dataset.filter; update(); }));
clear.addEventListener('click', () => { input.value = ''; update(); input.focus(); });
document.querySelector('#reset-search').addEventListener('click', () => { selected = 'all'; input.value = ''; update(); input.focus(); });
input.addEventListener('keydown', event => { if (event.key === 'Escape') { input.value = ''; update(); } });
update();

